            rewardItems = {{20802, 1}},
        },
        [8778] = {
            description = "The Ironforge Brigade has put in an unusual request for highly... volatile... " ..
                "components. Gather them and bring them to Mr. Nozzlespring from the Ironforge Brigade.",
            rewardItems = {{20800, 1}, {20805, 1}},
        },
        [8783] = {
            description = "Vargus, Cenarion Hold's blacksmith, has requested enchanted materials to be " ..
                "used in the crafting of powerful weapons for our forces. Obtain these and bring them " ..
                "directly to Vargus so that Cenarion Hold's troops may continue to be well equipped.",
            rewardItems = {{20800, 1}, {21132, 1}},
        },
        [8785] = {
            description = "The Orgrimmar Legion has put in a request for several unusual ingredients. " ..
                "Given their current performance in Silithus, we'd like to comply with their request as " ..
                "soon as possible. Gather the materials and bring them to the troll called Shai.",
            rewardItems = {{20800, 1}, {21386, 1}},
        },
        [8787] = {
            description = "The brave volunteers of the Orgrimmar Legion have arrived to Silithus to aid " ..
                "us in our cause. Their supplies of armor kits were somehow lost in the trip. Obtain a " ..
                "batch of armor kits and deliver them to Merok Longstride at the location of the " ..
                "Orgrimmar Legion camp.",
            rewardItems = {{20800, 1}, {21386, 1}},
        },
        [8790] = {
            description = "Arygos theorizes that the element which is born of conflicts between the Old " ..
                "Gods and their minions is also extremely deadly to them under the right conditions. I " ..
                "speak of Elementium, mortal.\n\nFind and bring me Imperial Qiraji Regalia and the toxic " ..
                "element and I shall infuse weapons of great power.",
            rewardChoices = {{21273, 1}, {21275, 1}, {21268, 1}},
            rewardXP = 6600,
        },
        [8794] = {
            description = "Hello, I'm glad that you've decided to hear me out. The Horde needs all of the " ..
                "help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! " ..
                "Even now as we speak, official collectors are gathering the necessary material needed " ..
                "for the upcoming war, but we won't be able to meet our goals without your assistance, " ..
                "<name>!\n\nYou should go speak with the guy in charge, Warlord Gorchuk. What do you say, " ..
                "<class>? Will you help out with the vital preparations?",
        },
        [8795] = {
            description = "Hello, I'm glad that you've decided to hear me out. The Alliance needs all of " ..
                "the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need " ..
                "you! Even now as we speak, official collectors are gathering the necessary material " ..
                "needed for the upcoming war, but we won't be able to meet our goals without your " ..
                "assistance, <name>!\n\nYou should go speak with the guy in charge, Field Marshal " ..
                "Snowfall. What do you say, <class>? Will you help out with the vital preparations?",
        },
        [8796] = {
            description = "Hello, I'm glad that you've decided to hear me out. The Alliance needs all of " ..
                "the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need " ..
                "you! Even now as we speak, official collectors are gathering the necessary material " ..
                "needed for the upcoming war, but we won't be able to meet our goals without your " ..
                "assistance, <name>!\n\nYou should go speak with the guy in charge, Field Marshal " ..
                "Snowfall. What do you say, <class>? Will you help out with the vital preparations?",
        },
        [8801] = {
            description = "The walls of Ahn'Qiraj tremble. A force of evil, older than the world itself, " ..
                "has been destroyed.\n\nAs you look at the remnants of the colossal abomination your " ..
                "heart nearly freezes. Even in death you can feel the legacy of C'Thun's evil around " ..
                "you.\n\nYou have done what was thought to be impossible.\n\nYou grab at an eye stalk of " ..
                "the fiend, stowing it safely in your pack.\n\nTake the Eye of C'Thun to the dragons in " ..
                "the next chamber.",
        },
        [8802] = {
            description = "To the Caverns of Time you go, <Lord/Lady> <name>. Anachronos awaits your " ..
                "return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his " ..
                "master's collection.",
            rewardChoices = {{21712, 1}, {21710, 1}, {21709, 1}},
        },
        [8804] = {
            description = "With the arrival of fresh recruits to Cenarion Hold comes the problem of " ..
                "keeping them alive in the desert. Dehydration as well as numerous poisonous creatures " ..
                "present a serious threat to inexperienced volunteers. Gather the supplies necessary for " ..
                "a desert survival kit and bring them to Calandrath in Cenarion Hold.",
            rewardItems = {{20800, 1}, {21266, 1}},
        },
        [8806] = {
            description = "The Cenarion Hold guard is in short supply of grinding stones. Procure a batch " ..
                "and deliver them immediately to Captain Vish Kozus in Cenarion Hold.",
            rewardItems = {{20800, 1}, {21266, 1}},
        },
        [8807] = {
            description = "Geologist Larksbane 's studies have proven to be of tremendous value to our " ..
                "operations in Silithus. She has recently requested scrying materials to be used in her " ..
                "research.\n\nPlease gather these materials and deliver them to her directly so that she " ..
                "may continue her research.",
            rewardItems = {{20800, 1}, {21386, 1}},
        },
        [8808] = {
            description = "The latest influx of volunteers has caused a shortage of uniforms. Procure a " ..
                "batch of uniform materials and bring them to Windcaller Proudhorn.",
            rewardItems = {{20800, 1}, {21266, 1}},
        },
        [8809] = {
            description = "Vargus, Cenarion Hold's blacksmith, has requested enchanted materials to be " ..
                "used in the crafting of powerful weapons for our forces. Obtain these and bring them " ..
                "directly to Vargus so that Cenarion Hold's troops may continue to be well equipped.",
            rewardItems = {{20800, 1}, {21266, 1}},
        },
